interface FormProps<T> {
  initialValues: T;
  onSubmit: (values: T) => void;
  children: (values: T, handleChange: (field: keyof T, value: T[keyof T]) => void) => ReactNode;
}

function Form<T extends object>({ initialValues, onSubmit, children }: FormProps<T>) {
  const [values, setValues] = useState<T>(initialValues);

  const handleChange = (field: keyof T, value: T[keyof T]) => {
    setValues(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(values);
  };

  return (
    <form onSubmit={handleSubmit}>
      {children(values, handleChange)}
    </form>
  );
}

// Usage
interface LoginForm {
  email: string;
  password: string;
}

<Form<LoginForm>
  initialValues={{ email: '', password: '' }}
  onSubmit={(values) => console.log(values)}
>
  {(values, handleChange) => (
    <>
      <input value={values.email} onChange={(e) => handleChange('email', e.target.value)} />
      <input type="password" value={values.password} onChange={(e) => handleChange('password', e.target.value)} />
    </>
  )}
</Form>
